function artifacts=auditCovarianceAwareFinalizeArtifacts(cfg,out,T,testMode)
%AUDITCOVARIANCEAWAREFINALIZEARTIFACTS Gate, summarize, and write final files.
schema=auditCovarianceAwareFinalValidation50Schema();localGate(T,cfg,testMode);S=localSummary(T);P=localPaired(T);B=localBootstrap(T,cfg);H=localHashes(T);D=T(:,cellstr(schema.detectionAlignment));R=T(:,cellstr(schema.rdaAudit));U=localRuntime(T);
writetable(T,fullfile(out,schema.files.packetLevel));writetable(S,fullfile(out,schema.files.summary));writetable(P,fullfile(out,schema.files.pairedStatistics));writetable(B,fullfile(out,schema.files.bootstrapCi));writetable(H,fullfile(out,schema.files.pairingHashes));writetable(D,fullfile(out,schema.files.detectionAlignment));writetable(R,fullfile(out,schema.files.rdaAudit));writetable(U,fullfile(out,schema.files.runtimeAudit));
localManifest(cfg,out,schema);localReport(cfg,out,T,S,P,B,schema);save(fullfile(out,schema.files.resultsMat),'cfg','T','S','P','B','H','D','R','U','-v7.3');
artifacts=struct('summary',S,'paired',P,'bootstrap',B,'hashes',H,'alignment',D,'rda',R,'runtime',U);
end

function localGate(T,cfg,testMode)
expected=numel(cfg.Ncodeword)*cfg.packetCountPerCondition*numel(cfg.methods);assert(height(T)==expected,'Expected %d rows, found %d.',expected,height(T));keys=unique(T(:,{'payloadSymbols','packetIndex'}),'rows');
for i=1:height(keys),x=T(T.payloadSymbols==keys.payloadSymbols(i)&T.packetIndex==keys.packetIndex(i),:);assert(height(x)==6&&numel(unique(x.method))==6&&all(ismember(cfg.methods,x.method)));names={'sharedHashH','sharedHashY','sharedHashTxBits','paddingBitHash','paddingSymbolHash','paddingReCount'};for j=1:numel(names),assert(isscalar(unique(x.(names{j}))),'Pairing mismatch in %s.',names{j});end,end
assert(all(T.futureSymbolReadCount==0)&all(T.solverFailureCount==0)&all(T.paddingDaUseCount==0)&all(T.sameSymbolFeedbackCount==0));ordinary=ismember(T.method,cfg.methods(1:4));assert(all(T.testTruthOnlineUseCount(ordinary)==0));core={'avgCsiNmse','preLdpcBer','goodputMbps','softEvm','processingTimeSec'};for i=1:numel(core),assert(all(isfinite(T.(core{i}))),'Nonfinite core metric %s.',core{i});end
if ~testMode,for i=1:numel(cfg.methods),x=T(T.method==cfg.methods(i),:);assert(height(x)==100&&nnz(x.payloadSymbols==cfg.Npayload(1))==50&&nnz(x.payloadSymbols==cfg.Npayload(2))==50);end,end
end
function S=localSummary(T)
keys=unique(T(:,{'payloadSymbols','method'}),'rows');C=cell(height(keys),1);for i=1:height(keys),x=T(T.payloadSymbols==keys.payloadSymbols(i)&T.method==keys.method(i),:);evm2=mean(x.softEvmSquared);C{i}=table(keys.payloadSymbols(i),keys.method(i),height(x),mean(x.avgCsiNmse),median(x.avgCsiNmse),std(x.avgCsiNmse),mean(x.worstStreamNmse),mean(x.p95ReError),mean(x.p99ReError),mean(x.deepFadeNmse),mean(x.preLdpcBer),mean(x.postLdpcBer,'omitnan'),mean(x.codewordPassRate),mean(x.goodputMbps),mean(x.softEvm),evm2,10*log10(1/max(evm2,eps)),median(x.processingTimeSec),mean(x.processingTimeSec),'VariableNames',auditCovarianceAwareFinalValidation50Schema().summary);end;S=vertcat(C{:});
end
function P=localPaired(T)
refs=["BaseKalmanCausal_EP","FixedRadius3Causal_EP","OJCD_LMMSE_EP_Adapted","OracleDataAidedCausal_EP","PerfectCSI_EP"];metrics=["avgCsiNmse","worstStreamNmse","p95ReError","p99ReError","deepFadeNmse","preLdpcBer","softEvm","goodputMbps","processingTimeSec"];lower=[true true true true true true true false true];payloads=unique(T.payloadSymbols);C=cell(numel(payloads)*numel(refs)*(numel(metrics)+1),1);n=0;for payload=payloads.',for r=1:numel(refs),a=sortrows(T(T.payloadSymbols==payload&T.method=="CovarianceAwareLocalDAKalmanCausal_EP",:),'packetIndex');b=sortrows(T(T.payloadSymbols==payload&T.method==refs(r),:),'packetIndex');assert(all(a.packetIndex==b.packetIndex));for m=1:numel(metrics),d=a.(metrics(m))-b.(metrics(m));tol=1e-12;pm=mean(a.(metrics(m)));rm=mean(b.(metrics(m)));if lower(m),wins=nnz(d<-tol);loss=nnz(d>tol);rel=(rm-pm)/rm*100;else,wins=nnz(d>tol);loss=nnz(d<-tol);rel=(pm-rm)/rm*100;end;if rm==0,rel=NaN;end;n=n+1;C{n}=table(payload,"CovarianceAwareLocalDAKalmanCausal_EP",refs(r),metrics(m),numel(d),pm,rm,mean(d),median(d),wins,loss,numel(d)-wins-loss,rel,lower(m),NaN,NaN,NaN,NaN,NaN,NaN,NaN,'VariableNames',auditCovarianceAwareFinalValidation50Schema().pairedStatistics);end;ap=a.codewordPass>0;bp=b.codewordPass>0;n=n+1;C{n}=table(payload,"CovarianceAwareLocalDAKalmanCausal_EP",refs(r),"codewordPass",numel(ap),mean(ap),mean(bp),mean(double(ap)-double(bp)),median(double(ap)-double(bp)),nnz(ap&~bp),nnz(~ap&bp),nnz(ap==bp),NaN,false,nnz(ap&bp),nnz(~ap&~bp),nnz(ap&~bp),nnz(~ap&bp),mean(ap),mean(bp),mean(ap)-mean(bp),'VariableNames',auditCovarianceAwareFinalValidation50Schema().pairedStatistics);end,end;P=vertcat(C{:});
end
function B=localBootstrap(T,cfg)
P=localPaired(T);P=P(P.metric~="codewordPass",:);C=cell(height(P)*2,1);cursor=0;state=rng;cleanup=onCleanup(@()rng(state));for i=1:height(P),a=sortrows(T(T.payloadSymbols==P.payloadSymbols(i)&T.method==P.proposedMethod(i),:),'packetIndex');b=sortrows(T(T.payloadSymbols==P.payloadSymbols(i)&T.method==P.referenceMethod(i),:),'packetIndex');av=a.(P.metric(i));bv=b.(P.metric(i));d=av-bv;rng(cfg.bootstrapSeed+i,'twister');means=zeros(cfg.bootstrapCount,1);rels=zeros(cfg.bootstrapCount,1);for q=1:cfg.bootstrapCount,idx=randi(numel(d),numel(d),1);pm=mean(av(idx));rm=mean(bv(idx));means(q)=mean(d(idx));if rm==0,rels(q)=NaN;elseif P.lowerIsBetter(i),rels(q)=(rm-pm)/rm*100;else,rels(q)=(pm-rm)/rm*100;end,end;cursor=cursor+1;C{cursor}=localBootRow(P(i,:),"meanPairedDifference",mean(d),means,cfg);cursor=cursor+1;C{cursor}=localBootRow(P(i,:),"relativeImprovementPercent",P.relativeImprovementPercent(i),rels,cfg);end;B=vertcat(C{1:cursor});
end
function row=localBootRow(p,label,estimate,samples,cfg),row=table(p.payloadSymbols,p.proposedMethod,p.referenceMethod,p.metric+":"+label,cfg.bootstrapCount,cfg.bootstrapSeed,estimate,auditDeterministicPercentile(samples,.025),auditDeterministicPercentile(samples,.975),.95,'VariableNames',auditCovarianceAwareFinalValidation50Schema().bootstrapCi);end
function H=localHashes(T),keys=unique(T(:,{'payloadSymbols','packetIndex'}),'rows');C=cell(height(keys),1);for i=1:height(keys),x=T(T.payloadSymbols==keys.payloadSymbols(i)&T.packetIndex==keys.packetIndex(i),:);C{i}=table(keys.payloadSymbols(i),keys.packetIndex(i),x.conditionSeed(1),x.packetSeed(1),x.sharedHashH(1),x.sharedHashY(1),x.sharedHashTxBits(1),x.paddingBitHash(1),x.paddingSymbolHash(1),x.paddingReCount(1),true,'VariableNames',auditCovarianceAwareFinalValidation50Schema().pairingHashes);end;H=vertcat(C{:});end
function U=localRuntime(T),keys=unique(T(:,{'payloadSymbols','method'}),'rows');C=cell(height(keys),1);for i=1:height(keys),x=T(T.payloadSymbols==keys.payloadSymbols(i)&T.method==keys.method(i),:);base=T(T.payloadSymbols==keys.payloadSymbols(i)&T.method=="BaseKalmanCausal_EP",:);fixed=T(T.payloadSymbols==keys.payloadSymbols(i)&T.method=="FixedRadius3Causal_EP",:);C{i}=table(keys.payloadSymbols(i),keys.method(i),height(x),mean(x.processingTimeSec),median(x.processingTimeSec),std(x.processingTimeSec),auditDeterministicPercentile(x.processingTimeSec,.95),mean(x.processingTimeSec)/mean(base.processingTimeSec),mean(x.processingTimeSec)/mean(fixed.processingTimeSec),'VariableNames',auditCovarianceAwareFinalValidation50Schema().runtimeAudit);end;U=vertcat(C{:});end
function localManifest(cfg,out,schema)
f=fopen(fullfile(out,schema.files.manifest),'w','n','UTF-8');assert(f>=0);c=onCleanup(@()fclose(f));fprintf(f,'experimentName=%s\nvalidationSeed=%d\nbootstrapSeed=%d\nMATLAB=%s\ntimestamp=%s\npayloadSymbols=%s\npacketCountPerCondition=%d\nmethods=%s\nfixedRadius=3\ncandidateSet=[1 2 3]\ndevelopmentSeed=20260720\nllrThreshold=2.5\nminEffectiveSamples=2\ngramRcondThreshold=0.001\nRDA=RLS\nNIS=false\nalpha_nis=false\nalpha_dec=false\ndynamicRadius=false\nJoseph=true\npaddingExcluded=true\nnoSameSymbolFeedback=true\nmaxDaUpdatesPerTarget=1\nstateOrder=Re(H11),Re(H21),Re(H12),Re(H22),Im(H11),Im(H21),Im(H12),Im(H22)\ncovarianceVectorOrder=H11,H21,H12,H22\ncomplexTranspose=nonconjugate\nrealMapping=0.5*[Re(C),-Im(C);Im(C),Re(C)]\neigenFloor=absolute_and_relative_frozen_floor\nbootstrapCount=%d\nschemaVersion=%s\n',cfg.experimentName,cfg.validationSeed,cfg.bootstrapSeed,version,string(datetime('now')),mat2str(cfg.Npayload),cfg.packetCountPerCondition,strjoin(cfg.methods,','),cfg.bootstrapCount,schema.version);
files={fullfile(cfg.root,'Audit_ThreeLayer_Base_Oracle_Proposed.m'),fullfile(fileparts(mfilename('fullpath')),'auditCovarianceAwareFinalValidation50.m'),fullfile(fileparts(mfilename('fullpath')),'auditCovarianceAwareFinalValidation50RunCore.m'),fullfile(fileparts(mfilename('fullpath')),'auditMechanismRunSingleEstimator.m'),fullfile(cfg.root,'audit_three_layer_helpers','ojcd_baseline','auditOjcdTwoLayerSymbol.m'),fullfile(fileparts(mfilename('fullpath')),'auditCovarianceAwareFinalValidation50Config.m'),fullfile(fileparts(mfilename('fullpath')),'auditCovarianceAwareFinalValidation50Schema.m')};for i=1:numel(files),fprintf(f,'SHA256 %s %s\n',localSha(files{i}),files{i});end
end
function h=localSha(path),fid=fopen(path,'rb');assert(fid>=0);c=onCleanup(@()fclose(fid));bytes=fread(fid,inf,'*uint8');md=java.security.MessageDigest.getInstance('SHA-256');md.update(bytes);h=lower(reshape(dec2hex(typecast(md.digest(),'uint8'),2).',1,[]));end
function localReport(cfg,out,T,S,P,B,schema),f=fopen(fullfile(out,schema.files.report),'w','n','UTF-8');assert(f>=0);c=onCleanup(@()fclose(f));fprintf(f,['Frozen independent validation, not a tuning run.\nDevelopment seed=%d; validation seed=%d.\nMethods: %s\nParameters frozen: radius=3, RDA=RLS, no NIS/alpha/dynamic radius.\n' ...
'Rows=%d; pairing groups=%d; future reads=%g; ordinary truth leaks=%g; solver failures=%g; padding DA uses=%g; same-symbol feedback=%g.\nSummary rows=%d; paired rows=%d; bootstrap rows=%d.\n' ...
'softEvm is packet RMS normalized symbol error. Aggregate effective SINR is 10log10(1/mean(softEvm^2)); packet dB values are not arithmetically averaged.\n' ...
'codewordPass is whole-payload all-codewords-pass; codewordPassRate uses decoded codewords as denominator and therefore differs between one- and three-codeword payloads.\n' ...
'Known limitation: postLdpcBer is unavailable from the frozen receiver API and is recorded as NaN. COMPLETE is created only after artifacts and complete checkpoint are saved.\n'],cfg.developmentSeed,cfg.validationSeed,strjoin(cfg.methods,','),height(T),height(unique(T(:,{'payloadSymbols','packetIndex'}),'rows')),sum(T.futureSymbolReadCount),sum(T.testTruthOnlineUseCount(ismember(T.method,cfg.methods(1:4)))),sum(T.solverFailureCount),sum(T.paddingDaUseCount),sum(T.sameSymbolFeedbackCount),height(S),height(P),height(B));end
